def transform(grid):
    n = len(grid)
    k = n // 2
    cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 5]
    count = len(cells)

    out = [[7] * n for _ in range(n)]
    horizontal = sum(all(v == 0 for v in row) for row in grid) > 1

    if horizontal:
        for c in range(n):
            out[k - 1][c] = 0
            out[k + 1][c] = 0
        for r in range(n):
            out[r][k] = 0
        start = k - count // 2
        for c in range(start, start + count):
            out[k][c] = 5
    else:
        for r in range(n):
            out[r][k - 1] = 0
            out[r][k + 1] = 0
        for c in range(n):
            out[k][c] = 0
        start = k - count // 2
        for r in range(start, start + count):
            out[r][k] = 5

    return out
